class Solution {
  public int maxTaskAssign(int[] tasks, int[] workers, int pills, int strength) {
    Arrays.sort(tasks);
    Arrays.sort(workers);
    int lo = 0, hi = Math.min(tasks.length, workers.length);
    while (lo < hi) {
      int mid = (lo + hi + 1) >>> 1;
      if (canDo(tasks, workers, pills, strength, mid)) lo = mid;
      else hi = mid - 1;
    }
    return lo;
  }

  // the k easiest tasks against the k strongest workers
  private boolean canDo(int[] tasks, int[] workers, int pills, int strength, int k) {
    Deque<Integer> reachable = new ArrayDeque<>(); // tasks a pill-boosted worker could take
    int next = 0;
    for (int i = workers.length - k; i < workers.length; i++) {
      while (next < k && tasks[next] <= workers[i] + strength) reachable.addLast(tasks[next++]);
      if (reachable.isEmpty()) return false;
      if (reachable.peekFirst() <= workers[i]) {
        reachable.pollFirst(); // can do the easiest task unaided
      } else {
        if (pills == 0) return false;
        pills--;
        reachable.pollLast(); // use the pill on the hardest task still within reach
      }
    }
    return true;
  }
}
